import{lt as e,q as t,ut as n,wt as r}from"./chunks/framework.DadrUYml.js";var i=JSON.parse(`{"title":"Exams","description":"SCUT undergraduate exams, deferred exam application guide, and exam preparation resources","frontmatter":{"lang":"en-US","title":"Exams","description":"SCUT undergraduate exams, deferred exam application guide, and exam preparation resources","llm_translated":true},"headers":[],"relativePath":"en/learn/curricular/exam.md","filePath":"en/learn/curricular/exam.md","lastUpdated":1793435255000}`),a={name:`en/learn/curricular/exam.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/learn/curricular/exam.md for this page in Markdown format</div><h1 id="exams" tabindex="-1">Exams <a class="header-anchor" href="#exams" aria-label="Permalink to “Exams”">​</a></h1><p>TODO: Add exam regulations and guidelines:</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Exam room discipline and violation handling: serious consequences and academic sanctions for bringing phones/cheating</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Grade review and appeal: process and time window for requesting a review of disputed final grades</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Course assessment methods: assessment formats and grade composition for different course types (required/elective/general education)</li></ul><h2 id="deferred-exam" tabindex="-1">Deferred Exam <a class="header-anchor" href="#deferred-exam" aria-label="Permalink to “Deferred Exam”">​</a></h2><p><a href="./deferred_exam">Deferred Exam Application Guide</a> is a verified SOP based on two actual applications, covering illness and schedule-conflict evidence, the application form, dual-department approval and three official stamps, receipt delivery, and the next-semester retake enrollment confirmation.</p><h2 id="self-directed-learning-science-and-technology" tabindex="-1">Self-Directed Learning: Science and Technology <a class="header-anchor" href="#self-directed-learning-science-and-technology" aria-label="Permalink to “Self-Directed Learning: Science and Technology”">​</a></h2><p><a href="./self_study_science_technology">Self-Directed Learning: Science and Technology — Anti-Involution Survival Engineering for College Students</a> is a complete methodology for university final exams, discussing target score management, subject triage, reverse-engineering past exam papers, exam-room control, and how to use Agents to turn scattered materials into an executable review system.</p><h2 id="final-review-tools" tabindex="-1">Final Review Tools <a class="header-anchor" href="#final-review-tools" aria-label="Permalink to “Final Review Tools”">​</a></h2><p>When preparation time is limited and course materials are scattered, <a href="https://github.com/Wh1te358/exam-hacker" target="_blank" rel="noreferrer">Exam Hacker</a> can turn textbooks, slides, past papers, and notes into a target-score-driven study plan.</p><p>It consists of one entry skill and five specialist skills. The workflow triages the materials, target, and available time; compresses knowledge chains; solves complete problems; runs active drills; and replans from mastery evidence. For scanned PDFs, it first checks readability and treats only inspected pages as visual evidence.</p><h2 id="course-pdf-downloader" tabindex="-1">Course PDF Downloader <a class="header-anchor" href="#course-pdf-downloader" aria-label="Permalink to “Course PDF Downloader”">​</a></h2><p>When a PDF in the SCUT course center has a preview entry but no download button, use the <a href="https://github.com/Wh1te358/scut-course-pdf-downloader" target="_blank" rel="noreferrer">SCUT Course PDF Downloader</a> Chrome extension. It supports direct PDF URLs and PDF.js preview pages whose addresses contain the original PDF URL.</p><p>The current version handles PDFs only, not PPT, PPTX, videos, or course home pages. Its repository README includes installation, testing, and usage instructions.</p><h2 id="university-physics" tabindex="-1">University Physics <a class="header-anchor" href="#university-physics" aria-label="Permalink to “University Physics”">​</a></h2><p>Here are <em>Oplisty</em>&#39;s <strong>SCUT University Physics Review Notes</strong>: <a href="https://www.zhihu.com/column/c_1888956732467823738" target="_blank" rel="noreferrer">University Physics Theorem Summary Express Edition</a></p><p>Useful for studying and reviewing University Physics Part 1.</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};